create or replace package body atm_api as
  function withdraw(p_account_no in varchar2, p_amount in number) return varchar2 is
    l_current_balance bank_accounts.balance%type;
    l_overdraft_limit bank_accounts.overdraft_limit%type;
    l_new_balance bank_accounts.balance%type;
  begin
    -- Get current balance and overdraft limit
    select balance, overdraft_limit into l_current_balance, l_overdraft_limit
    from bank_accounts
    where account_no = p_account_no;

    -- Calculate potential new balance
    l_new_balance := l_current_balance - p_amount;

    -- Check if the new balance exceeds the allowed overdraft limit
    -- The limit is defined as the maximum negative balance allowed.
    -- If l_new_balance < -l_overdraft_limit, it means the withdrawal exceeds the limit.
    if l_new_balance < (-l_overdraft_limit) then
      return 'DECLINED';
    end if;

    -- If within limits, perform the update
    update bank_accounts
      set balance = l_new_balance
    where account_no = p_account_no;

    return 'OK';
  exception
    when no_data_found then
      -- Handle case where account_no is not found, although not explicitly tested, it's good practice
      return 'DECLINED';
  end withdraw;

  function balance_of(p_account_no in varchar2) return number is
    l_balance bank_accounts.balance%type;
  begin
    select balance into l_balance from bank_accounts where account_no = p_account_no;
    return l_balance;
  end balance_of;
end atm_api;
